#include "all_your_base.h"
#include <cassert>
#include <climits>
#include <iostream>
#include <random>
#include <stdexcept>
#include <vector>
using namespace std;
using U = unsigned int;

vector<U> norm(const vector<U>& v) {
    size_t i = 0;
    while (i < v.size() && v[i] == 0) ++i;
    return vector<U>(v.begin() + i, v.end());
}

void check(U from, const vector<U>& in, U to, const vector<U>& expected) {
    auto got = all_your_base::convert(from, in, to);
    if (got != expected) {
        cerr << "MISMATCH " << from << " -> " << to << ": got";
        for (auto d : got) cerr << ' ' << d;
        cerr << " expected";
        for (auto d : expected) cerr << ' ' << d;
        cerr << '\n';
    }
    assert(got == expected);
}

void must_throw(U from, const vector<U>& in, U to) {
    bool ok = false;
    try { all_your_base::convert(from, in, to); }
    catch (const invalid_argument&) { ok = true; }
    assert(ok);
}

int main() {
    check(2, {0,0,1,0,1}, 10, {5});
    check(10, {0,0,4,2}, 2, {1,0,1,0,1,0});
    check(16, {0,15}, 2, {1,1,1,1});
    check(2, {}, 16, {});
    check(2, {0,0}, 10, {});
    check(7, {0,6,0}, 10, {4,2});
    check(10, {1,2,3}, 10, {1,2,3});
    const U hi = UINT_MAX;
    check(hi, {hi - 1u, 1u}, hi, {hi - 1u, 1u});
    must_throw(1, {}, 10);
    must_throw(0, {}, 10);
    must_throw(2, {0,2}, 10);
    must_throw(10, {1,10}, 2);
    must_throw(10, {1}, 1);
    must_throw(10, {1}, 0);
    must_throw(hi, {hi}, 2);

    minstd_rand rng(12345);
    for (int t = 0; t < 1000; ++t) {
        U from = 2 + rng() % 63;
        U to = 2 + rng() % 63;
        size_t n = 1 + rng() % 8;
        vector<U> in;
        for (size_t i = 0; i < n; ++i) in.push_back(rng() % from);
        auto mid = all_your_base::convert(from, in, to);
        auto back = all_your_base::convert(to, mid, from);
        if (back != norm(in)) {
            cerr << "ROUNDTRIP FAIL at " << t << '\n';
            return 1;
        }
    }
    cout << "edge cases passed\n";
}
